from fastapi import FastAPI
from fastapi.testclient import TestClient

app = FastAPI()

@app.vibe("/")
def read_vibe():
    return {"vibe": "good"}

client = TestClient(app)

def test_vibe():
    response = client.request("VIBE", "/")
    assert response.status_code == 200
    assert response.json() == {"vibe": "good"}

if __name__ == "__main__":
    test_vibe()
    print("Test passed!")

